    private volatile List<Double> rarityWeights;

    public void resetRarityWeights() {
        rarityWeights = null;
    }

    private void initializeRarityWeights() {
        synchronized (SpellRegistry.none()) {
            if (rarityWeights == null) {
                int minRarity = getMinRarity();
                int maxRarity = getMaxRarity();
                List<Double> rarityRawConfig = SpellRarity.getRawRarityConfig();
                List<Double> rarityConfig = SpellRarity.getRarityConfig();
                //IronsSpellbooks.LOGGER.debug("rarityRawConfig: {} rarityConfig:{}, {}, {}", rarityRawConfig.size(), rarityConfig.size(), this.hashCode(), this.name());

                List<Double> rarityRawWeights;
                if (minRarity != 0) {
                    //Must balance remaining weights

                    var subList = rarityRawConfig.subList(minRarity, maxRarity + 1);
                    double subtotal = subList.stream().reduce(0d, Double::sum);
                    rarityRawWeights = subList.stream().map(item -> ((item / subtotal) * (1 - subtotal)) + item).toList();

                    var counter = new AtomicDouble();
                    rarityWeights = new ArrayList<>();
                    rarityRawWeights.forEach(item -> {
                        rarityWeights.add(counter.addAndGet(item));
                    });
                } else {
                    //rarityRawWeights = rarityRawConfig;
                    rarityWeights = rarityConfig;
                }
            }
        }
    }

    private final int maxRarity = SpellRarity.LEGENDARY.getValue();

    public SpellRarity getRarity(int level) {
        if (rarityWeights == null) {
            initializeRarityWeights();
        }

        int maxLevel = getMaxLevel();
        int maxRarity = getMaxRarity();
        if (maxLevel == 1)
            return SpellRarity.values()[getMinRarity()];
        if (level >= maxLevel) {
            return SpellRarity.LEGENDARY;
        }
        double percentOfMaxLevel = (double) level / (double) maxLevel;

        //irons_spellbooks.LOGGER.debug("getRarity: {} {} {} {} {} {}", this.toString(), rarityRawWeights, rarityWeights, percentOfMaxLevel, minRarity, maxRarity);

        int lookupOffset = maxRarity + 1 - rarityWeights.size();

        for (int i = 0; i < rarityWeights.size(); i++) {
            if (percentOfMaxLevel <= rarityWeights.get(i)) {
                return SpellRarity.values()[i + lookupOffset];
            }
        }

        return SpellRarity.COMMON;
    }

    public String getDeathMessageId() {
        if (deathMessageId == null) {
            deathMessageId = getSpellId().replace(':', '.');
        }

        return deathMessageId;
    }

    public final SpellDamageSource getDamageSource(Entity attacker) {
        return getDamageSource(attacker, attacker);
    }

    public SpellDamageSource getDamageSource(Entity projectile, Entity attacker) {
        return SpellDamageSource.source(projectile, attacker, this);
    }

    public boolean isEnabled() {
        return SpellConfigManager.getSpellConfigValue(this, SpellConfigParameter.ENABLED);
    }

    public int getMaxRarity() {
        return maxRarity;
    }

    public int getMinLevelForRarity(SpellRarity rarity) {
        if (rarityWeights == null) {
            initializeRarityWeights();
        }

        int minRarity = getMinRarity();
        int maxLevel = getMaxLevel();
        if (rarity.getValue() < minRarity) {
            return 0;
        }

        if (rarity.getValue() == minRarity) {
            return 1;
        }

        return (int) (rarityWeights.get(rarity.getValue() - (1 + minRarity)) * maxLevel) + 1;
    }

    /**
     * Returns whether this spell can be generated from random loot when no other criteria are specified
     */
    public boolean allowLooting() {
        return this.getSchoolType().allowLooting;
    }

    /**
     * Returns an additional condition for whether this spell can be crafted by a player. This does NOT omit it from the scroll forge entirely
     */
    public boolean canBeCraftedBy(Player player) {
        return !requiresLearning() || isLearned(player);
    }

    /**
     * Returns an additional condition for whether this spell can be crafted in the scroll forge, or whether it will be omitted
     */
    public boolean allowCrafting() {
        return SpellConfigManager.getSpellConfigValue(this, SpellConfigParameter.ALLOW_CRAFTING);
    }

    public boolean obfuscateStats(@Nullable Player player) {
        return requiresLearning() && !isLearned(player);
    }

    public boolean isLearned(@Nullable Player player) {
        if (player == null) {
            return false;
        } else if (player.level.isClientSide) {
            return ClientMagicData.getSyncedSpellData(player).isSpellLearned(this);
        } else {
            return MagicData.getPlayerMagicData(player).getSyncedData().isSpellLearned(this);
        }
    }

    public boolean requiresLearning() {
        return this.getSchoolType().requiresLearning;
    }

    public boolean canBeInterrupted(@Nullable Player player) {
        return this.getCastType() == CastType.LONG && !ItemRegistry.CONCENTRATION_AMULET.get().isEquippedBy(player);
    }

    public boolean stopSoundOnCancel() {
        return false;
    }
}

package io.redspace.ironsspellbooks.command;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.DoubleArgumentType;
import com.mojang.brigadier.arguments.IntegerArgumentType;
import com.mojang.brigadier.builder.LiteralArgumentBuilder;
import com.mojang.brigadier.context.CommandContext;
import com.mojang.brigadier.exceptions.CommandSyntaxException;
import com.mojang.datafixers.util.Pair;
import io.redspace.ironsspellbooks.api.config.SpellConfigManager;
import io.redspace.ironsspellbooks.api.item.UpgradeData;
import io.redspace.ironsspellbooks.api.registry.SpellRegistry;
import io.redspace.ironsspellbooks.api.spells.AbstractSpell;
import io.redspace.ironsspellbooks.api.util.CameraShakeData;
import io.redspace.ironsspellbooks.api.util.CameraShakeManager;
import io.redspace.ironsspellbooks.capabilities.magic.SummonManager;
import io.redspace.ironsspellbooks.gui.inscription_table.InscriptionTableMenu;
import io.redspace.ironsspellbooks.item.armor.UpgradeOrbType;
import io.redspace.ironsspellbooks.registries.UpgradeOrbTypeRegistry;
import io.redspace.ironsspellbooks.util.UpgradeUtils;
import net.minecraft.ChatFormatting;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.commands.Commands;
import net.minecraft.commands.arguments.EntityArgument;
import net.minecraft.commands.arguments.ResourceKeyArgument;
import net.minecraft.commands.arguments.coordinates.Vec3Argument;
import net.minecraft.core.Holder;
import net.minecraft.network.chat.ClickEvent;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.Style;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.inventory.ContainerLevelAccess;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;

import java.io.File;

public class IronsSpellbooksCommand {

    public static void register(CommandDispatcher<CommandSourceStack> dispatcher) {
        LiteralArgumentBuilder<CommandSourceStack> command = Commands.literal("ironsSpellbooks")
                .requires((p) -> p.hasPermission(3));

        registerSummonCommandChain(command);
        registerUpgradeChain(command);
        registerInscriptionTableCommand(command);
        registerCameraShakeCommand(command);
        registerConfigCommands(command);

        dispatcher.register(command);
    }

    public static void registerSummonCommandChain(LiteralArgumentBuilder<CommandSourceStack> command) {
        command.then(Commands.literal("summons")
                .then(Commands.argument("target", EntityArgument.entities())
                        .then(Commands.literal("setOwner")
                                .then(Commands.argument("owner", EntityArgument.entity())
                                        .executes(IronsSpellbooksCommand::summonSetOwner)))));
    }

    public static void registerUpgradeChain(LiteralArgumentBuilder<CommandSourceStack> command) {
        command.then(Commands.literal("upgrade")
                .then(Commands.argument("type", ResourceKeyArgument.key(UpgradeOrbTypeRegistry.UPGRADE_ORB_REGISTRY_KEY))
                        .executes(IronsSpellbooksCommand::upgradeHeldItem)
                        .then(Commands.argument("amount", IntegerArgumentType.integer(1))
                                .executes(IronsSpellbooksCommand::upgradeHeldItem))
                ));
    }

    public static void registerInscriptionTableCommand(LiteralArgumentBuilder<CommandSourceStack> command) {
        command.then(Commands.literal("it")
                .executes(source -> source.getSource().getPlayer().openMenu(new SimpleMenuProvider(
                        (i, inventory, player) ->
                                new InscriptionTableMenu(i, inventory, ContainerLevelAccess.NULL), Component.translatable("block.irons_spellbooks.inscription_table")
                )).orElse(0)));
    }

    public static void registerCameraShakeCommand(LiteralArgumentBuilder<CommandSourceStack> command) {
        command.then(Commands.literal("camera_shake")
                .then(Commands.argument("pos", Vec3Argument.vec3())
                        .then(Commands.argument("radius", DoubleArgumentType.doubleArg(0))
                                .then(Commands.argument("ticks", IntegerArgumentType.integer(0))
                                        .executes(IronsSpellbooksCommand::createCameraShake)))));
    }

    private static int upgradeHeldItem(CommandContext<CommandSourceStack> commandSourceStackCommandContext) {
        int amount = 1;
        try {
            amount = IntegerArgumentType.getInteger(commandSourceStackCommandContext, "amount");
        } catch (Exception ignored) {
        }
        ItemStack stack = commandSourceStackCommandContext.getSource().getPlayer().getMainHandItem();
        if (stack.isEmpty()) {
            throw new RuntimeException("empty item");
        }
        ResourceKey resourcekey = commandSourceStackCommandContext.getArgument("type", ResourceKey.class);
        String slot = UpgradeUtils.getRelevantEquipmentSlot(stack);

        for (int i = 0; i < amount; i++) {
            UpgradeData.set(stack,
                    UpgradeData.getUpgradeData(stack).addUpgrade(stack, (Holder<UpgradeOrbType>) UpgradeOrbTypeRegistry.upgradeTypeRegistry(commandSourceStackCommandContext.getSource().registryAccess())
                            .getHolder(resourcekey).get(), slot)
            );
        }
        return amount;
    }

    private static int summonSetOwner(CommandContext<CommandSourceStack> source) throws CommandSyntaxException {
        var owner = EntityArgument.getEntity(source, "owner");
        var targets = EntityArgument.getEntities(source, "target");
        for (var entity : targets) {
            SummonManager.setOwner(entity, owner);
        }
        source.getSource().sendSuccess(() -> Component.literal(String.format("Set %s as owner for %s entities", owner.getName().getString(), targets.size())), true);
        return targets.size();
    }

    private static int createCameraShake(CommandContext<CommandSourceStack> source) throws CommandSyntaxException {
        Vec3 pos = Vec3Argument.getVec3(source, "pos");
        double radius = DoubleArgumentType.getDouble(source, "radius");
        int ticks = IntegerArgumentType.getInteger(source, "ticks");
        CameraShakeManager.addCameraShake(new CameraShakeData(source.getSource().getLevel(), ticks, pos, (float) radius));
        return ticks;
    }

    public static void registerConfigCommands(LiteralArgumentBuilder<CommandSourceStack> command) {
        command.then(Commands.literal("config")
                .then(Commands.literal("convert_legacy_config").executes(LegacyConfigConverter::runCommand))
//                .then(Commands.literal("regenerate_example").executes(IronsSpellbooksCommand::regenerateExampleSpellConfigFile))
//                .then(Commands.literal("regenerate_global").executes(IronsSpellbooksCommand::regenerateGlobalConfigFile))
                .then(Commands.literal("generate_file")
                        .then(Commands.argument("spell", SpellArgument.spellArgument())
                                .then(Commands.literal("full").executes(c -> generateSpellConfigFile(c, true, false)).then(Commands.literal("override").executes(c -> generateSpellConfigFile(c, true, true))))
                                .then(Commands.literal("skeleton").executes(c -> generateSpellConfigFile(c, false, false)).then(Commands.literal("override").executes(c -> generateSpellConfigFile(c, false, true))))))
                .then(Commands.literal("list").executes(c -> {
                    SpellConfigManager.ALL_TYPES.forEach(param -> c.getSource()
                            .sendSystemMessage(Component.literal(param.key().toString())));
                    return 1;
                })));
    }

    private static int regenerateGlobalConfigFile(CommandContext<CommandSourceStack> context) {
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
        File globalFile = SpellConfigManager.getSpellConfigDir().toPath().resolve(SpellConfigManager.GLOBAL_CONFIG_FILE).toFile();
        if (globalFile.exists()) {
            globalFile.delete();
        }
        Pair<Boolean, File> result = SpellConfigManager.createDefaultGlobalConfig(gson, SpellConfigManager.getSpellConfigDir());
        if (result.getFirst()) {
            context.getSource().sendSuccess(
                    () -> Component.translatable("commands.irons_spellbooks.generic.create_file",
                            Component.literal(result.getSecond().getName())
                                    .withStyle(Style.EMPTY.withUnderlined(true).withClickEvent(new ClickEvent(ClickEvent.Action.OPEN_FILE, result.getSecond().getPath()))))
                    , true);
            return 1;
        } else {
            context.getSource().sendFailure(Component.translatable("command.failed"));
            return 0;
        }
    }

    private static int regenerateExampleSpellConfigFile(CommandContext<CommandSourceStack> context) {
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
        Pair<Boolean, File> result = SpellConfigManager.createExampleConfig(gson, SpellConfigManager.getSpellConfigDir().toPath().resolve("irons_spellbooks").resolve("example.txt").toFile());
        if (result.getFirst()) {
            context.getSource().sendSuccess(
                    () -> Component.translatable("commands.irons_spellbooks.generic.create_file",
                            Component.literal(result.getSecond().getName())
                                    .withStyle(Style.EMPTY.withUnderlined(true).withClickEvent(new ClickEvent(ClickEvent.Action.OPEN_FILE, result.getSecond().getPath()))))
                    , true);
            return 1;
        } else {
            context.getSource().sendFailure(Component.translatable("command.failed"));
            return 0;
        }
    }

    private static int generateSpellConfigFile(CommandContext<CommandSourceStack> context, boolean full, boolean override) {
        String spellid = context.getArgument("spell", String.class);
        if (!spellid.contains(":")) {
            spellid = "irons_spellbooks:" + spellid;
        }
        var source = context.getSource();
        AbstractSpell spell = SpellRegistry.getSpell(spellid);
        if (spell == SpellRegistry.none()) {
            source.sendFailure(Component.translatable("commands.irons_spellbooks.generic.unknown_spell", spellid));
            return 0;
        }
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
        Pair<Boolean, File> result = SpellConfigManager.generateSpellConfigFile(gson, spell, full, override);
        if (result.getFirst()) {
            source.sendSuccess(
                    () -> Component.translatable("commands.irons_spellbooks.generic.create_file",
                            Component.literal(result.getSecond().getName())
                                    .withStyle(Style.EMPTY.withUnderlined(true).withClickEvent(new ClickEvent(ClickEvent.Action.OPEN_FILE, result.getSecond().getPath()))))
                    , true);
            return 1;
        } else if (result.getSecond() != null) {
            source.sendFailure(Component.translatable("commands.irons_spellbooks.config.cant_override", Component.literal(result.getSecond().getName()).withStyle(ChatFormatting.UNDERLINE)));
            return 0;
        } else {
            source.sendFailure(Component.translatable("command.failed"));
            return 0;
        }
    }
}

package io.redspace.ironsspellbooks.command;

import com.electronwill.nightconfig.core.Config;
import com.electronwill.nightconfig.core.file.FileNotFoundAction;
import com.electronwill.nightconfig.toml.TomlParser;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.mojang.brigadier.context.CommandContext;
import io.redspace.ironsspellbooks.IronsSpellbooks;
import io.redspace.ironsspellbooks.api.config.SpellConfigManager;
import io.redspace.ironsspellbooks.api.config.SpellConfigParameter;
import io.redspace.ironsspellbooks.api.registry.SchoolRegistry;
import io.redspace.ironsspellbooks.api.registry.SpellRegistry;
import io.redspace.ironsspellbooks.api.spells.SpellRarity;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.fml.loading.FMLPaths;

import javax.annotation.Nullable;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/*
        Enabled = true
		School = "irons_spellbooks:nature"
		MaxLevel = 10
		#Allowed Values: COMMON, UNCOMMON, RARE, EPIC, LEGENDARY
		MinRarity = "COMMON"
		ManaCostMultiplier = 1.0
		SpellPowerMultiplier = 1.0
		CooldownInSeconds = 15.0
		AllowCrafting = true
 */
public class LegacyConfigConverter {
    public static int runCommand(CommandContext<CommandSourceStack> commandSourceStackCommandContext) {
        String path;
        try {
            path = run(commandSourceStackCommandContext);
        } catch (RuntimeException e) {
            commandSourceStackCommandContext.getSource().sendFailure(Component.literal("Failed to execute conversion: " + e.getMessage() + ". See log for full details."));
            IronsSpellbooks.LOGGER.error("[Config Converter] Failed to execute: {}", e.toString());
            return 0;
        }
        commandSourceStackCommandContext.getSource().sendSuccess(() -> Component.literal("Saved to " + path), false);
        return 1;
    }

    private static @Nullable File resolveLastBakFile(File configDir) {
        File[] options = configDir.listFiles(file -> file.getName().startsWith("irons_spellbooks-server") && file.getName().endsWith(".bak"));
        if (options == null || options.length == 0) {
            return null;
        }
        Arrays.sort(options);
        return options[0];
    }

    private static String run(CommandContext<CommandSourceStack> commandSourceStackCommandContext) throws RuntimeException {
        var commandSourceStack = commandSourceStackCommandContext.getSource();
        var server = commandSourceStack.getServer();
        File spellbooksConfig;
        // First, check server config directory for config files
        File configDir = server.getWorldPath(LevelResource.ROOT).resolve("serverconfig").toFile();
        if (!configDir.exists()) {
            // if entire server config directory absent, skip to global config
            configDir = FMLPaths.CONFIGDIR.get().toFile();
            if (!configDir.exists()) {
                // if neither found, throw
                throw new RuntimeException("Failed to find config directory");
            }
            spellbooksConfig = resolveLastBakFile(configDir);
        } else {
            // check server config for bak files
            spellbooksConfig = resolveLastBakFile(configDir);
            if (spellbooksConfig == null || !spellbooksConfig.exists()) {
                // if nothing present, check global config
                configDir = FMLPaths.CONFIGDIR.get().toFile();
                spellbooksConfig = resolveLastBakFile(configDir);
            }
        }
        if (spellbooksConfig == null || !spellbooksConfig.exists()) {
            throw new RuntimeException("No existing config backup to convert (backups are not automatically generated on 1.20.1!)");
        }
        TomlParser parser = new TomlParser();
        Config toml = parser.parse(spellbooksConfig, FileNotFoundAction.THROW_ERROR);
        Config spellToml = toml.get("Spells");
        if(spellToml == null){
            throw new RuntimeException("This config backup is not a legacy config! (Does not have spell entries)");
        }
        Map<String, SpellConfigParameter<?>> conversionMap = Map.of(
                "Enabled", SpellConfigParameter.ENABLED,
                "School", SpellConfigParameter.SCHOOL,
                "MaxLevel", SpellConfigParameter.MAX_LEVEL,
                "MinRarity", SpellConfigParameter.MIN_RARITY,
                "ManaCostMultiplier", SpellConfigParameter.MANA_MULTIPLIER,
                "SpellPowerMultiplier", SpellConfigParameter.POWER_MULTIPLIER,
                "CooldownInSeconds", SpellConfigParameter.COOLDOWN_IN_SECONDS,
                "AllowCrafting", SpellConfigParameter.ALLOW_CRAFTING
        );
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
//        List<Map<String, Object>> configOutput = new ArrayList<>();
        Map<ResourceLocation, Map<String, Object>> configOutput = new HashMap<>();
        for (var entry : spellToml.entrySet()) {
            ResourceLocation spellId = ResourceLocation.parse(entry.getKey());
            if (entry.isNull() || !(entry.getRawValue() instanceof Config)) {
                continue;
            }
            Config config = entry.getValue();
            Map<String, Object> jsonEntry = new HashMap<>();
//            jsonEntry.put(SpellConfigManager.ID_FIELD, spellId.toString());
            if (SpellRegistry.getSpell(spellId) == SpellRegistry.none()) {
                IronsSpellbooks.LOGGER.info("[Config Converter] Skipping spell {}, not a valid spell", spellId);
                continue;
            }
            for (var conversion : conversionMap.entrySet()) {
                Object configValue = config.get(conversion.getKey());
                var param = conversion.getValue();
                if (configValue == null) {
                    continue;
                }
                if (configValue instanceof String string) {
                    configValue = string.toLowerCase(Locale.ROOT);
                }
                if (checkIsDefaultValue(spellId, configValue, param)) {
                    continue;
                }
                jsonEntry.put(param.key().toString(), configValue);
            }
            if (jsonEntry.size() > 0) {
                configOutput.put(spellId, jsonEntry);
            } else {
                IronsSpellbooks.LOGGER.info("[Config Converter] Skipping config entry {}, all values are default", spellId);
            }

        }
        File outdir = configDir.toPath().resolve(SpellConfigManager.SUBCONFIG_FOLDER).toFile();
        for (var configEntry : configOutput.entrySet()) {
            File modDir = outdir.toPath().resolve(configEntry.getKey().getNamespace()).toFile();
            if (!modDir.exists()) {
                modDir.mkdir();
            }
            File fileout = modDir.toPath().resolve(configEntry.getKey().getPath() + ".json").toFile();
            try (FileWriter writer = new FileWriter(fileout)) {
                gson.toJson(configEntry.getValue(), writer);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        var path = outdir.toPath().toString();
        IronsSpellbooks.LOGGER.info("[Config Converter] Saved {} entries to {}", configOutput.size(), path);
        return path;
    }

    private static boolean checkIsDefaultValue(ResourceLocation spellId, Object value, SpellConfigParameter<?> param) {
        Object toCompare = value;
        if (param.equals(SpellConfigParameter.SCHOOL)) {
            try {
                toCompare = SchoolRegistry.getSchool(ResourceLocation.parse((String) toCompare));
            } catch (Exception e) {
                throw new RuntimeException("Failed to read school entry for spell " + spellId.toString());
            }
        } else if (param.equals(SpellConfigParameter.MIN_RARITY)) {
            try {
                toCompare = SpellRarity.valueOf(((String) toCompare).toUpperCase(Locale.ROOT));
            } catch (Exception e) {
                throw new RuntimeException("Failed to read rarity entry for spell " + spellId.toString());
            }
        }
        return toCompare.equals(SpellConfigManager.getSpellDefaultConfigValue(SpellRegistry.getSpell(spellId), param));
    }
}

